"""The SereneDB wordmark, from the logo SVG, as tube segments.

Each letter is filled with horizontal tubes clipped to its outline, plus a tube along
the outline itself, so it renders as a solid letter with rounded edges.
"""
import re

CAP = 6.0   # cap height of the letters, in scene units, before a Wordmark scales them

