def outlines(n=8):
    """Closed polylines of the path; cubic curves are flattened to n segments."""
    tokens = re.findall(r"[MCLHVZ]|-?\d*\.?\d+(?:e-?\d+)?", PATH)
    polys, cur, i, pos = [], [], 0, (0.0, 0.0)
    while i < len(tokens):
        cmd = tokens[i]
        i += 1
        nums = []
        while i < len(tokens) and not tokens[i].isalpha():
            nums.append(float(tokens[i]))
            i += 1
        if cmd == "M":
            if cur:
                polys.append(cur)
            pos = (nums[0], nums[1])
            cur = [pos]
            for j in range(2, len(nums), 2):
                pos = (nums[j], nums[j + 1])
                cur.append(pos)
        elif cmd == "L":
            for j in range(0, len(nums), 2):
                pos = (nums[j], nums[j + 1])
                cur.append(pos)
        elif cmd == "H":
            for x in nums:
                pos = (x, pos[1])
                cur.append(pos)
        elif cmd == "V":
            for y in nums:
                pos = (pos[0], y)
                cur.append(pos)
        elif cmd == "C":
            for j in range(0, len(nums), 6):
                p0, p1, p2, p3 = pos, nums[j:j + 2], nums[j + 2:j + 4], nums[j + 4:j + 6]
                for k in range(1, n + 1):
                    t = k / n
                    a, b, c, d = (1 - t) ** 3, 3 * (1 - t) ** 2 * t, 3 * (1 - t) * t * t, t ** 3
                    cur.append((a * p0[0] + b * p1[0] + c * p2[0] + d * p3[0],
                                a * p0[1] + b * p1[1] + c * p2[1] + d * p3[1]))
                pos = (nums[j + 4], nums[j + 5])
        elif cmd == "Z":
            if cur:
                if cur[0] != cur[-1]:
                    cur.append(cur[0])
                polys.append(cur)
                pos, cur = cur[0], []
    if cur:
        polys.append(cur)
    return polys


def layout(height=CAP, step=0.3):
    """Segments of the wordmark with its baseline at y = 0 and its caps `height` high
    (y up), its width, and how many of the segments (the first ones) are the outline;
    the rest fill the letters. `step` is the spacing of the fill tubes."""
    polys = outlines()
    xs = [x for p in polys for x, _ in p]
    ys = [y for p in polys for _, y in p]
    x0, y_base, y_top = min(xs), max(ys), min(ys)
    k = height / (y_base - y_top)
    polys = [[((x - x0) * k, (y_base - y) * k) for x, y in p] for p in polys]
    edges = [(a, b) for p in polys for a, b in zip(p, p[1:])]
    segs = list(edges)
    y = step / 2
    while y < height:
        # Even-odd spans of the horizontal line at y.
        hits = sorted(a[0] + (y - a[1]) * (b[0] - a[0]) / (b[1] - a[1])
                      for a, b in edges if (a[1] <= y) != (b[1] <= y))
        segs += [((hits[j], y), (hits[j + 1], y)) for j in range(0, len(hits) - 1, 2)]
        y += step
    return segs, (max(xs) - x0) * k, len(edges)
